interface Animal {
    void sound();
}

class Dog implements Animal {
    public void sound(){
        System.out.println("Dog Barks");
    }
}

interface Printable {
    void print();
}

interface Scannable {
    void scan();
}

class Printer implements Printable, Scannable {
    public void print(){}
    public void scan(){}
}

interface Vehicle {
    default void start(){
        System.out.println("Vehicle Started");
    }
}
